solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

void putVarint(std::vector<std::uint8_t>& out, std::uint64_t value)
{
    while (value >= 0x80)
    {
        out.push_back(static_cast<std::uint8_t>(value | 0x80));
        value >>= 7;
    }
    out.push_back(static_cast<std::uint8_t>(value));
}

std::optional<std::uint64_t> getVarint(const std::vector<std::uint8_t>& in, std::size_t& at)
{
    std::uint64_t value{ 0 };
    for (int i{ 0 }; i < 10; ++i)
    {
        if (at + i >= in.size()) return std::nullopt;
        const std::uint8_t b{ in[at + i] };
        value |= static_cast<std::uint64_t>(b & 0x7F) << (7 * i);
        if (!(b & 0x80)) { at += i + 1; return value; }
    }
    return std::nullopt;
}

std::uint64_t zigzag(std::int64_t n) { return (static_cast<std::uint64_t>(n) << 1) ^ static_cast<std::uint64_t>(n >> 63); }
std::int64_t unzigzag(std::uint64_t z) { return static_cast<std::int64_t>(z >> 1) ^ -static_cast<std::int64_t>(z & 1); }

struct Settings { std::optional<std::string> name; std::optional<std::int64_t> volume; std::optional<bool> fullscreen; };

static void field(std::vector<std::uint8_t>& out, std::uint64_t tag, const std::vector<std::uint8_t>& value)
{
    putVarint(out, tag);
    putVarint(out, value.size());
    out.insert(out.end(), value.begin(), value.end());
}

std::vector<std::uint8_t> encodeSettings(const Settings& s)
{
    std::vector<std::uint8_t> out;
    if (s.name) field(out, 1, { s.name->begin(), s.name->end() });
    if (s.volume) { std::vector<std::uint8_t> v; putVarint(v, zigzag(*s.volume)); field(out, 2, v); }
    if (s.fullscreen) field(out, 3, { static_cast<std::uint8_t>(*s.fullscreen ? 1 : 0) });
    return out;
}

std::optional<Settings> decodeSettings(const std::vector<std::uint8_t>& bytes)
{
    Settings s;
    std::size_t at{ 0 };
    while (at < bytes.size())
    {
        const auto tag{ getVarint(bytes, at) };
        if (!tag) return std::nullopt;
        const auto length{ getVarint(bytes, at) };
        if (!length || *length > bytes.size() - at) return std::nullopt;
        const std::vector<std::uint8_t> value(bytes.begin() + static_cast<std::ptrdiff_t>(at), bytes.begin() + static_cast<std::ptrdiff_t>(at + *length));
        at += *length;
        if (*tag == 1)
        {
            if (s.name) return std::nullopt;
            s.name = std::string(value.begin(), value.end());
        }
        else if (*tag == 2)
        {
            if (s.volume) return std::nullopt;
            std::size_t inner{ 0 };
            const auto z{ getVarint(value, inner) };
            if (!z || inner != value.size()) return std::nullopt;
            s.volume = unzigzag(*z);
        }
        else if (*tag == 3)
        {
            if (s.fullscreen || value.size() != 1 || value[0] > 1) return std::nullopt;
            s.fullscreen = value[0] == 1;
        }
    }
    return s;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("varints") {
    Bytes b;
    putVarint(b, 1); putVarint(b, 127); putVarint(b, 128); putVarint(b, 300);
    CHECK(b == (Bytes{ 0x01, 0x7F, 0x80, 0x01, 0xAC, 0x02 }));
    std::size_t at{ 0 };
    CHECK_EQ(getVarint(b, at).value_or(9), 1ull);
    CHECK_EQ(getVarint(b, at).value_or(9), 127ull);
    CHECK_EQ(getVarint(b, at).value_or(9), 128ull);
    CHECK_EQ(getVarint(b, at).value_or(9), 300ull);
    CHECK_EQ(at, b.size());
    Bytes big;
    putVarint(big, ~0ull);
    CHECK_EQ(big.size(), 10u);
    std::size_t z{ 0 };
    CHECK_EQ(getVarint(big, z).value_or(0), ~0ull);
}
TEST("bad varints") {
    std::size_t at{ 0 };
    CHECK(!getVarint(Bytes{ 0x80, 0x80 }, at).has_value());
    at = 0;
    CHECK(!getVarint(Bytes(11, 0x80), at).has_value());
}
TEST("zigzag") {
    CHECK_EQ(zigzag(0), 0ull); CHECK_EQ(zigzag(-1), 1ull); CHECK_EQ(zigzag(1), 2ull); CHECK_EQ(zigzag(-2), 3ull);
    for (std::int64_t n : { 0ll, 5ll, -5ll, 123456789ll, -9000000000ll }) CHECK_EQ(unzigzag(zigzag(n)), n);
}
TEST("settings round trip and the exact bytes") {
    const Settings s{ "AdaMs", 75, std::nullopt };
    const Bytes wire{ encodeSettings(s) };
    CHECK(wire == (Bytes{ 0x01, 0x05, 'A', 'd', 'a', 'M', 's', 0x02, 0x02, 0x96, 0x01 }));
    const auto back{ decodeSettings(wire) };
    CHECK(back.has_value());
    if (back) { CHECK_EQ(back->name.value_or(""), std::string("AdaMs")); CHECK_EQ(back->volume.value_or(0), 75); CHECK(!back->fullscreen.has_value()); }
    CHECK(decodeSettings({}).has_value());
}
TEST("unknown fields are skipped, broken ones refused") {
    Bytes wire{ 0x09, 0x02, 0xAA, 0xBB };
    const Bytes known{ encodeSettings(Settings{ std::nullopt, -3, true }) };
    wire.insert(wire.end(), known.begin(), known.end());
    const auto s{ decodeSettings(wire) };
    CHECK(s.has_value());
    if (s) { CHECK_EQ(s->volume.value_or(0), -3); CHECK(s->fullscreen.value_or(false)); }
    CHECK(!decodeSettings(Bytes{ 0x01, 0x09, 'x' }).has_value());
    CHECK(!decodeSettings(Bytes{ 0x03, 0x01, 0x02 }).has_value());
    CHECK(!decodeSettings(Bytes{ 0x03, 0x01, 0x01, 0x03, 0x01, 0x00 }).has_value());
    CHECK(!decodeSettings(Bytes{ 0x02, 0x02, 0x05, 0x00 }).has_value());
}

